import re
from datetime import datetime


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        import json
        data = json.loads(text)
    except (json.JSONDecodeError, TypeError, ValueError):
        raise ValueError("Invalid JSON")

    if not isinstance(data, list):
        raise ValueError("Expected a JSON array")

    if data:
        row_count = len(data)
        total_cents = 0
        first_day = None
        last_day = None

        for row in data:
            if not isinstance(row, dict):
                raise ValueError("Expected JSON array of objects")

            tenant = row.get("tenant")
            amount_cents = row.get("amount_cents")
            day = row.get("day")

            if not tenant or not isinstance(tenant, str):
                raise ValueError("Invalid tenant field")
            if tenant == "":
                raise ValueError("Tenant must be nonempty")
            if not isinstance(amount_cents, int) or isinstance(amount_cents, bool):
                raise ValueError("Invalid amount_cents field (must be integer, not boolean)")
            if not isinstance(day, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", day):
                raise ValueError("Invalid day field")

            try:
                parsed_day = datetime.strptime(day, "%Y-%m-%d")
            except ValueError:
                raise ValueError(f"Invalid date: {day}")

            total_cents += amount_cents

            if first_day is None or parsed_day < first_day:
                first_day = day
            if last_day is None or parsed_day > last_day:
                last_day = day

        return {
            "row_count": row_count,
            "total_cents": total_cents,
            "first_day": first_day,
            "last_day": last_day
        }

    return {
        "row_count": 0,
        "total_cents": 0,
        "first_day": None,
        "last_day": None
    }"}

